INSERT IGNORE INTO school_content (Collection, Title, Slug, Category, Summary, Body, ImageUrl, Status, PublishedAt, SortOrder) VALUES ('berita', 'Pekan Bahasa Jadi Panggung Kreativitas Siswa', 'pekan-bahasa-panggung-kreativitas-siswa', 'Kegiatan siswa', 'Dari membaca puisi hingga bercerita dalam bahasa Inggris, siswa tampil percaya diri dalam perayaan Bulan Bahasa.', 'Suasana aula sekolah terasa berbeda saat siswa bergantian membawakan puisi, cerita pendek, dan penampilan bahasa. Setiap kelas menyiapkan karya dengan tema persahabatan dan semangat belajar.
INSERT IGNORE INTO school_content (Collection, Title, Slug, Category, Summary, Body, ImageUrl, Status, PublishedAt, SortOrder) VALUES ('berita', 'Dari Ruang Kelas ke Pameran Sains', 'pameran-sains-karya-dari-ruang-kelas', 'Pembelajaran', 'Siswa memamerkan percobaan sederhana dan menjelaskan ide di balik karya mereka kepada teman serta guru.', 'Meja-meja di ruang kegiatan berubah menjadi tempat pameran hasil eksperimen siswa. Ada penyaring air sederhana, model energi alternatif, dan percobaan yang berangkat dari pertanyaan sehari-hari.
INSERT IGNORE INTO school_content (Collection, Title, Slug, Category, Summary, Body, ImageUrl, Status, PublishedAt, SortOrder) VALUES ('berita', 'OSIS Ajak Warga Sekolah Bergerak di Jumat Bersih', 'aksi-jumat-bersih-oleh-osis', 'OSIS', 'Lewat aksi bersama, siswa merawat taman, memilah sampah, dan menata kembali sudut belajar di sekolah.', 'Pengurus OSIS mengajak setiap kelas mengambil bagian dalam kegiatan Jumat Bersih. Siswa membagi tugas untuk merapikan ruang kelas, membersihkan halaman, dan merawat tanaman di lingkungan sekolah.
INSERT IGNORE INTO school_content (Collection, Title, Slug, Category, Summary, Body, ImageUrl, Status, PublishedAt, SortOrder) VALUES ('berita', 'Class Meeting, Seru Bertanding dan Saling Mendukung', 'class-meeting-sportivitas-dan-kebersamaan', 'Olahraga', 'Pertandingan antarkelas menghadirkan semangat sportivitas, kerja sama tim, dan dukungan meriah dari teman-teman.', 'Sorak dukungan terdengar dari tepi lapangan saat pertandingan antarkelas dimulai. Siswa mengikuti permainan olahraga dan tantangan kelompok yang menuntut kekompakan, bukan hanya kemampuan individu.
INSERT IGNORE INTO school_content (Collection, Title, Slug, Category, Summary, Body, ImageUrl, Status, PublishedAt, SortOrder) VALUES ('pengumuman', 'Pengumuman Kegiatan Peringatan Hari Kemerdekaan', 'pengumuman-kegiatan-peringatan-hari-kemerdekaan', 'Informasi sekolah', 'Kegiatan peringatan Hari Kemerdekaan akan dilaksanakan di lingkungan sekolah. Siswa dapat menghubungi wali kelas untuk informasi jadwal dan perlengkapan.', 'Kegiatan peringatan Hari Kemerdekaan akan dilaksanakan di lingkungan sekolah. Siswa dapat menghubungi wali kelas untuk informasi jadwal dan perlengkapan.', '', 'Published', '2026-08-12 00:00:00', 0);
INSERT IGNORE INTO school_content (Collection, Title, Slug, Category, Summary, Body, ImageUrl, Status, PublishedAt, SortOrder) VALUES ('pengumuman', 'Informasi Libur Nasional dan Cuti Bersama', 'informasi-libur-nasional-dan-cuti-bersama', 'Informasi sekolah', 'Kegiatan belajar mengajar diliburkan mengikuti kalender pendidikan dan ketentuan hari libur nasional.', 'Kegiatan belajar mengajar diliburkan mengikuti kalender pendidikan dan ketentuan hari libur nasional.', '', 'Published', '2026-08-10 00:00:00', 1);
INSERT IGNORE INTO school_content (Collection, Title, Slug, Category, Summary, Body, ImageUrl, Status, PublishedAt, SortOrder) VALUES ('pengumuman', 'Lomba Kreativitas Siswa Tingkat Sekolah', 'lomba-kreativitas-siswa-tingkat-sekolah', 'Informasi sekolah', 'Siswa dapat mendaftarkan karya dan ide kreatif melalui wali kelas. Informasi kategori lomba tersedia di sekretariat sekolah.', 'Siswa dapat mendaftarkan karya dan ide kreatif melalui wali kelas. Informasi kategori lomba tersedia di sekretariat sekolah.', '', 'Published', '2026-08-03 00:00:00', 2);
